/**
 * Regression test for the Bulk Editor description fixes
 * (24 May 2026 — user reported "too many description sections,
 * really confused" + "description generated with supplier real
 * product name 'Pietra Ligure' but MUST be generated by Collection
 * Display Name 'La Dolce'").
 *
 * Contract pinned:
 *
 *   Fix 1 — UI simplification
 *     The duplicate "Description Template" Brief/Standard/Long
 *     generation buttons (purple pill row) were removed because:
 *       (a) the GREEN "Unified Series Description" card directly above
 *           already exposes Brief / Standard / Detailed buttons that
 *           use the correct (series-aware) endpoint.
 *       (b) the purple row called the per-product endpoint with the
 *           first sample product's name, which is exactly the bug that
 *           leaked the supplier name into the generated description.
 *     The Shorter / Longer / New buttons remain because they refine
 *     text that's already in the editor.
 *
 *   Fix 2 — Series-name extraction uses Collection Display Name
 *     The longest common prefix of admin-edited names
 *     (`our_product_name` / `display_name` / `website_name`) is the
 *     primary series-name signal. Supplier-side `original_series` /
 *     `series` fields are now strictly fallbacks.
 */
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const src = fs.readFileSync(
  path.join(__dirname, 'src/pages/admin/SupplierProducts.js'),
  'utf8',
);

// ── FIX 1 — UI simplification ───────────────────────────────────

// 1a. The purple Brief/Standard/Long generation row must NOT come back.
//     test-ids of those buttons are uniquely the signature.
assert.doesNotMatch(
  src,
  /data-testid="bulk-generate-brief-btn"/,
  'The redundant purple Brief generation button must be removed — ' +
    'the green Unified Series Description card already exposes it',
);
assert.doesNotMatch(
  src,
  /data-testid="bulk-generate-standard-btn"/,
  'The redundant purple Standard generation button must be removed',
);
assert.doesNotMatch(
  src,
  /data-testid="bulk-generate-long-btn"/,
  'The redundant purple Long generation button must be removed',
);

// 1b. The series-aware buttons in the green card must STILL be there.
assert.match(
  src,
  /data-testid="series-desc-brief-btn"/,
  'Green-card Brief button must remain — single source of truth for ' +
    'series description generation',
);
assert.match(
  src,
  /data-testid="series-desc-standard-btn"/,
  'Green-card Standard button must remain',
);
assert.match(
  src,
  /data-testid="series-desc-detailed-btn"/,
  'Green-card Detailed button must remain',
);

// 1c. The post-edit refinement controls (Shorter/Longer/New) must
//     remain because they refine existing editor text.
assert.match(src, /data-testid="bulk-make-shorter-btn"/);
assert.match(src, /data-testid="bulk-make-longer-btn"/);
assert.match(src, /data-testid="bulk-regenerate-btn"/);

// ── FIX 2 — Collection Display Name extraction ──────────────────

// 2a. The new code must build a longest-common-prefix from admin-edited
//     names (`our_product_name`/`display_name`/`website_name`).
assert.match(
  src,
  /const\s+adminNames\s*=\s*selectedProductsList[\s\S]{0,200}our_product_name[\s\S]{0,80}display_name[\s\S]{0,80}website_name/,
  'Series-name extraction must build an `adminNames` array from ' +
    'admin-edited fields, not supplier-side ones',
);

// 2b. The token-by-token common-prefix algorithm must be present.
assert.match(
  src,
  /tokenLists\.every\(tl\s*=>\s*tl\[i\]\s*===\s*token\)/,
  'Series name must be derived as the longest common token-prefix ' +
    'shared by every selected product\'s admin name',
);

// 2c. Trailing size/finish tokens must be stripped — e.g. "La Dolce"
//     not "La Dolce 60x60cm".
assert.match(
  src,
  /matt\|gloss\|polished\|natural\|satin\|honed\|brushed\|lappato/,
  'Trailing finish tokens (matt, gloss, polished, etc.) must be ' +
    'stripped from the derived series name',
);
assert.match(
  src,
  /\/\^\\d\/\.test\(last\)/,
  'Trailing tokens starting with a digit (60x60cm, 30x60cm) must be ' +
    'stripped from the derived series name',
);

// 2d. Old supplier-name-first logic must be a fallback, not the first
//     check. The new code reaches `firstProduct.original_series` only
//     inside `if (!seriesName)` after the common-prefix attempt.
const seriesNameCheckIndex = src.indexOf('commonPrefixTokens.join');
const firstProductOriginalIndex = src.indexOf('firstProduct.original_series');
assert.ok(
  seriesNameCheckIndex > 0 && firstProductOriginalIndex > seriesNameCheckIndex,
  '`firstProduct.original_series` lookup must come AFTER the common-' +
    'prefix computation so admin-edited names always win',
);

console.log('✓ bulk-editor-description-collection-name.test.js — all assertions passed');
